// Generated by Jjodel from the model cpu with the hw-cpu templates: the testbench of route A.
// It clocks the module and prints one line per cycle at the falling edge, after the rising edge has updated the
// registers (plan §7.4, risk R5): cycle 0 is the configuration Reset gives, and the run stops at a final state.
module tb;
  reg clk = 1'b1;
  integer cycle = 0;
  wire [3:0] state;
  wire [3:0] pc;
  wire [7:0] ir;
  wire [7:0] acc;
  wire [0:0] z;

  cpu dut (
    .clk(clk),
    .state(state),
    .pc(pc),
    .ir(ir),
    .acc(acc),
    .z(z)
  );

  always #5 clk = ~clk;

  always @(negedge clk) begin
    $display("%0d %0d %h %h %h %b", cycle, state, pc, ir, acc, z);
    if (state == 4'ha) $finish;
    if (cycle == 1000) $finish;
    cycle <= cycle + 1;
  end
endmodule
